pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address secondUser = address(0x123);
        // Try to call setOwner as non-admin user
        vm.prank(secondUser);
        try c.setOwner(secondUser) {
            // Call succeeded (buggy) – do nothing
        } catch {
            // Call reverted (correct) – do nothing
        }
        // In reference C, owner stays as deployer (this); in buggy M, owner becomes secondUser
        assertTrue(c.owner() == address(this));
    }
}

