// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deployer is both admin and owner initially
        address admin = address(this);
        address newOwner = address(0x222);
        address finalOwner = address(0x333);

        // First call: admin sets owner to newOwner (0x222)
        // Reference: succeeds (onlyAdmin passes)
        // Buggy M: also succeeds (onlyOwner passes because admin is still owner)
        bool ok1 = c.setOwner(newOwner);
        assertTrue(ok1);
        assertEq(c.owner(), newOwner);

        // Second call: admin tries to set owner to finalOwner (0x333)
        // Reference: succeeds (onlyAdmin passes, owner becomes 0x333)
        // Buggy M: reverts (onlyOwner fails because owner is now 0x222, not admin)
        bool ok2;
        try c.setOwner(finalOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Check the resulting owner value
        // Reference: owner == 0x333
        // Buggy M: owner == 0x222 (because second call reverted)
        // So assertTrue(c.owner() == finalOwner) passes on reference, fails on buggy M
        assertTrue(c.owner() == finalOwner);
    }
}

