pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Admin is the original deployer (this contract)
        address admin = address(this);
        // New owner we will assign
        address newOwner = address(0x1234);

        // Admin calls setOwner to change owner to newOwner
        c.setOwner(newOwner);

        // Now try calling setOwner again as admin (the original deployer).
        // Reference: onlyAdmin checks msg.sender == admin (still address(this)), so it succeeds.
        // Bug: onlyAdmin checks msg.sender == owner, which is now newOwner, so it reverts.
        bool ok;
        try c.setOwner(address(0x5678)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

